# --- Abgeleitete Einträge (Nachtrag): Lektionen-Werte, Modul-Codes, Breadcrumbs ---
# Diese waren zuvor faelschlich als "unveraenderlich" gefiltert worden.
_lek = (40, 48, 56, 64, 68, 72, 84, 104)
for _n in _lek:
    TRIPLES.append((f"{_n} Lektionen", f"{_n} leçons", f"{_n} lezioni"))

_mods = ["B1", "B2", "B3", "B4", "B5", "S1", "S2", "S3", "S4", "S5", "S6", "S7", "S8"]
for _c in _mods:
    TRIPLES.append((f"Modul {_c}", f"Module {_c}", f"Modulo {_c}"))

# Breadcrumb-Endsegmente ">&nbsp;/&nbsp; LABEL<" (Separator + Label in EINEM Textknoten)
_look = {de: (fr, it) for de, fr, it in TRIPLES}
_crumb_labels = ["Anmeldung", "Datenschutz", "Eidg. Fachausweis", "Kontakt",
                 "Veranstaltungen", "Weiterbildung", "Über uns"] + [f"Modul {_c}" for _c in _mods]
for _lab in _crumb_labels:
    _fr, _it = _look[_lab]
    TRIPLES.append((f"&nbsp;/&nbsp; {_lab}", f"&nbsp;/&nbsp; {_fr}", f"&nbsp;/&nbsp; {_it}"))
